toad_implementation.code_blueprint:
canvas {
  size: 800px 600px;
  fill: #FFFFFF;
  font-family: "Arial, sans-serif";
}

>carbon = #475569;
>oxygen = #EF4444;
>nitrogen = #0284C7;
>hydrogen = #94A3B8;
>bondLine = #334155;

text #figureHeader {
  at: top left of canvas offset 40px 40px;
  content: "Fig. 4b | Catalytic Cleavage Mechanism";
  font-size: 14px;
  font-weight: 700;
  color: #0F172A;
}

circle #atomCarbon1 {
  at: center of canvas offset -140px -40px;
  size: 50px;
  fill: >carbon;
}

text #labelC1 {
  at: center of #atomCarbon1;
  content: "C";
  font-size: 20px;
  font-weight: 700;
  color: #FFFFFF;
}

rect #bondDouble1 {
  at: right center of #atomCarbon1 offset 0px -6px;
  size: 80px 4px;
  fill: >bondLine;
}

rect #bondDouble2 {
  at: right center of #atomCarbon1 offset 0px 6px;
  size: 80px 4px;
  fill: >bondLine;
}

circle #atomOxygen1 {
  at: right of #atomCarbon1 offset 80px 0px;
  size: 50px;
  fill: >oxygen;
}

text #labelO1 {
  at: center of #atomOxygen1;
  content: "O";
  font-size: 20px;
  font-weight: 700;
  color: #FFFFFF;
}

rect #scaleBar {
  at: bottom left of canvas offset 40px -40px;
  size: 120px 4px;
  fill: #0F172A;
}

text #scaleLabel {
  at: below #scaleBar offset 8px;
  content: "1.5 Å (Angström)";
  font-size: 11px;
  color: #475569;
}
